export class AbstractBuiltinRule {
  /**
   * Normalise `{ plural: string[] }` into a clean, trimmed, non-empty string array.
   */
  normalizeList(config, plural) {
    const cfg = config || {};
    if (Array.isArray(cfg[plural])) {
      return cfg[plural].map(v => typeof v === 'string' ? v : String(v)).map(s => s.trim()).filter(s => s.length > 0);
    }
    return [];
  }
}
flarum.reg.add('huoxin-filter-rule-manager', 'forum/providers/builtin/AbstractBuiltinRule', { AbstractBuiltinRule: AbstractBuiltinRule, });